// Agent41 — recover all hidden-state LCGs modulo the original 1033/3301 clue values.
#include <algorithm>
#include <array>
#include <cassert>
#include <cmath>
#include <iostream>
#include <map>
#include <string>
#include <vector>
using namespace std;using V=vector<int>;using S=array<int,4>;
V dec(string s){V v;for(char c:s)v.push_back(c<='9'?c-'0':c-'a'+10);return v;}
int m; int mod29(int x){return(x+29)%29;}int mm(int x){x%=m;return x<0?x+m:x;}
struct G{int a,b,x;};int step(int x,G g){return (g.a*x+g.b)%m;}
V stream(G g,int n){V k;for(int i=0,x=g.x;i<n;i++,x=step(x,g))k.push_back(x%29);return k;}
vector<G> enumerate(S k){vector<G> out;for(int x=k[0];x<m;x+=29)for(int y=k[1];y<m;y+=29)for(int a=0;a<m;a++){int b=mm(y-a*x),z=(a*y+b)%m;if(z%29!=k[2])continue;int w=(a*z+b)%m;if(w%29==k[3])out.push_back({a,b,x});}return out;}
S keys(const V&c,int pos,S p){S k{};for(int i=0;i<4;i++)k[i]=mod29(c[pos+i]-p[i]);return k;}
int jump(G g,int n){int a=g.a,b=g.b,x=g.x;for(;n;n>>=1){if(n&1)x=(a*x+b)%m;b=(a*b+b)%m;a=a*a%m;}return x;}
bool match(G g,int x,S k){for(int j=0;j<4;j++,x=step(x,g))if(x%29!=k[j])return false;return true;}
bool legal(const V&c,const V&k,int lo,int hi,int forceH){vector<unsigned char>cur(forceH+1),next(forceH+1);cur[0]=1;for(int i=lo;i<hi;i++){fill(next.begin(),next.end(),0);bool any=false;for(int h=0;h<=forceH;h++)if(cur[h]){if(c[i]!=k[i-h]){next[h]=1;any=true;}if(c[i]==0&&h<forceH){next[h+1]=1;any=true;}}if(!any)return false;cur.swap(next);}return cur[forceH];}
double lp[29][29][29];double score(const V&p){double s=0;for(int i=2;i<(int)p.size();i++)s+=lp[p[i-2]][p[i-1]][p[i]];return s/(p.size()-2);}
V ordinary(const V&c,const V&k,int lo,int hi){V p;for(int i=lo;i<hi;i++)p.push_back(mod29(c[i]-k[i]));return p;}
double walk(const V&c,const V&k,int i,int j,int start,int x,int y,double sum){for(;i<(int)c.size();i++){if(c[i]==0){double h=walk(c,k,i+1,j,start,y,0,sum+(i>=start+2?lp[x][y][0]:0.));if(k[j]==0)return h;int z=29-k[j];return max(h,walk(c,k,i+1,j+1,start,y,z,sum+(i>=start+2?lp[x][y][z]:0.)));}if(c[i]==k[j])return -1e9;int z=mod29(c[i]-k[j++]);if(i>=start+2)sum+=lp[x][y][z];x=y;y=z;}return sum;}
double held(const V&c,const V&k,int lo,int j){return walk(c,k,lo,j,lo,0,0,0)/(c.size()-lo-2);}
void continuous(const V&c,int gap,S p0,S p1){S k0=keys(c,0,p0),k1=keys(c,gap,p1);auto gs=enumerate(k0);int zeros=count(c.begin()+4,c.begin()+gap,0),oc=0,hc=0,legalcount=0,fullcount=0;double fit=-1e9,hold=-1e9,maxheld=-1e9;G best{};for(G g:gs){int x=jump(g,gap-zeros);for(int j=gap-zeros;j<=gap;j++,x=step(x,g)){if(!match(g,x,k1))continue;hc++;auto k=stream(g,c.size());if(j==gap){oc++;double s=score(ordinary(c,k,4,gap)),t=score(ordinary(c,k,gap+4,c.size()));if(s>fit){fit=s;hold=t;best=g;}maxheld=max(maxheld,t);}if(!legal(c,k,4,gap,gap-j))continue;legalcount++;if(held(c,k,gap+4,j+4)>-1e6)fullcount++;}}
cout<<"CONT "<<m<<" first="<<gs.size()<<" ordinary="<<oc<<" hold_prefilter="<<hc<<" hold_prefix="<<legalcount<<" hold_full="<<fullcount<<" fit="<<fit<<" held="<<hold<<" max_held="<<maxheld<<" best="<<best.a<<','<<best.b<<','<<best.x<<"\n";}
void reset(const V&c1,const V&c2,S p0,S p1){auto g1=enumerate(keys(c1,0,p0)),g2=enumerate(keys(c2,0,p1));map<pair<int,int>,vector<G>> d;for(G g:g2)d[{g.a,g.b}].push_back(g);int pairs=0,legalpairs=0,ordinaryjoint=0,holdjoint=0;double bestf=-1e9,besth=-1e9,bestfh=-1e9,besthh=-1e9,maxh=-1e9,maxhh=-1e9;G best{},besthold{};int seed2=-1,seed2h=-1;for(G g:g1){auto it=d.find({g.a,g.b});if(it==d.end())continue;auto k=stream(g,c1.size());double f=score(ordinary(c1,k,4,c1.size())),fh=held(c1,k,4,4);for(G q:it->second){pairs++;auto l=stream(q,c2.size());double h=score(ordinary(c2,l,4,c2.size())),hh=held(c2,l,4,4);if(f>bestf){bestf=f;besth=h;best=g;seed2=q.x;}if(fh>-1e6&&hh>-1e6)legalpairs++;if(fh>bestfh){bestfh=fh;besthh=hh;besthold=g;seed2h=q.x;}if(f>=-3.320259963435666){maxh=max(maxh,h);if(h>=-3.221241329729617)ordinaryjoint++;}if(fh>=-3.320259963435666){maxhh=max(maxhh,hh);if(hh>=-3.221241329729617)holdjoint++;}}}cout<<"RESET "<<m<<" first="<<g1.size()<<" second="<<g2.size()<<" pairs="<<pairs<<" legalpairs="<<legalpairs<<" ordinaryjoint="<<ordinaryjoint<<" holdjoint="<<holdjoint<<" fit="<<bestf<<" held="<<besth<<" fitF="<<bestfh<<" heldF="<<besthh<<" maxheld="<<maxh<<" maxheldF="<<maxhh<<" best="<<best.a<<','<<best.b<<','<<best.x<<','<<seed2<<" bestF="<<besthold.a<<','<<besthold.b<<','<<besthold.x<<','<<seed2h<<"\n";}
V plant(V p,G g,bool hold){V c;int x=g.x;for(int y:p){if(hold&&y==0)c.push_back(0);else{c.push_back((y+x%29)%29);x=step(x,g);}}return c;}
int main(int argc,char**argv){string train,tape,p57;cin>>train>>tape>>p57;V tr=dec(train),c=dec(tape),donor=dec(p57);assert(tr.size()==3510&&c.size()==1779);int b[29][29]={},tri[29][29][29]={};for(int i=2;i<(int)tr.size();i++){b[tr[i-2]][tr[i-1]]++;tri[tr[i-2]][tr[i-1]][tr[i]]++;}for(int i=0;i<29;i++)for(int j=0;j<29;j++)for(int k=0;k<29;k++)lp[i][j][k]=log((tri[i][j][k]+1.)/(b[i][j]+29.));assert(abs(score(tr)+2.260728012730832)<1e-10);assert(abs(score(donor)+2.468144714244746)<1e-10);cout.precision(12);S p0={7,10,20,20},p1={13,24,2,15};for(int modulus:{1033,3301}){m=modulus;continuous(c,1619,p0,p1);reset(V(c.begin(),c.begin()+82),V(c.begin()+1619,c.end()),p0,p1);if(argc>1){V pp;for(int i=0;i<1779;i++)pp.push_back(donor[i%donor.size()]);copy(p0.begin(),p0.end(),pp.begin());copy(p1.begin(),p1.end(),pp.begin()+1619);for(bool h:{false,true}){cout<<"CONT PLANT "<<h<<" true 23,5,76\n";continuous(plant(pp,{23,5,76},h),1619,p0,p1);}V q1(p0.begin(),p0.end()),q2(p1.begin(),p1.end());V d1=dec("316819ni4fgo9nlo9ng32i3di98o9nin2ifs45803439i783f8okk4i5ia1iafb3q64sgi42o96a1l"),d2=dec("9n2i7oq0o4i4fo9n78i939i30q310okkfn3798i0okkf03423fihi8a9n8ajo5o1gr9o6oa9fg2ifg1jhklfg39ioqo9n8i0okkf03423fio8sn308aj783231680ofgi4o9nf14i430033gqig4ij31in93");q1.insert(q1.end(),d1.begin(),d1.end());q2.insert(q2.end(),d2.begin(),d2.end());for(bool h:{false,true}){cout<<"RESET PLANT "<<h<<" true 23,5,76,127\n";reset(plant(q1,{23,5,76},h),plant(q2,{23,5,127},h),p0,p1);}}}}
